# metrotrk: el depurador MetroTRK de Metrowerks, EN ENSAMBLADOR.
#
# No es C, y esta medido: 9.916 de sus 11.988 B leen registros no volatiles sin
# salvarlos o usan rfi/mtmsr/mtspr; ocho funciones salvan LR por r4 y tienen
# epilogos distintos entre vecinas; fn_80311440 lleva un bucle de retardo
# mtctr/bdnz y cmdReset acaba en `b cmdReset`. Todo el bloque materializa
# direcciones con `lis @h` mas `ori @l`, y SIETE compiladores --siete versiones
# de mwcc y ProDG 3.9.3-- no emiten @h/@l para un simbolo: todos dan @ha/addi.
# Y no hay ni una linea de DWARF en su rango, asi que no hay fuente que fundir.
#
# Por eso va como .s, igual que pro2D4.s: es el camino sancionado del proyecto
# para codigo que nunca fue C. Sustituye al metrotrk.c anterior, cuyos 148 B
# cerrados descansaban sobre asm() en linea.
.include "macros.inc"
.file "metrotrk.s"

# 0x8030EA7C..0x80311BE4 | size: 0x3168
.text
.balign 4

